#include "powder/plant.hpp"
#include <iostream>
#include <sstream>
#include <chrono>
#include <iomanip>
int main(int argc,char**argv){try{
 if(argc<2)throw std::runtime_error("source directory required");std::string root=argv[1];auto d=powder::read_plant_data(root+"/runtime.plant");auto routes=powder::read_plant_routes(root+"/runtime.routes");
 double radius=.01,length=1,q=1e-6;double expected=8*1.81e-5*length*q/(3.141592653589793*std::pow(radius,4));if(std::abs(powder::plant_cell_loss(q,length,radius)-expected)>1e-12)throw std::runtime_error("laminar analytic mismatch");
 for(double drop:{0.,25.,250.,1000.}){powder::solve_plant_pressure(d,routes,drop);for(auto&r:routes){double loss=0,first=d[r.cells[0]+2].x;for(int i:r.cells){auto a=d[i],b=d[i+1];if(d[i+2].x!=first)throw std::runtime_error("route continuity failure");loss+=powder::plant_cell_loss(first,std::hypot(std::hypot(b.x-a.x,b.y-a.y),b.z-a.z),d[i+2].z==1?2*a.w*b.w/(a.w+b.w):std::min(a.w,b.w),d[i+2].y,d[i+2].z==1?4*a.w*b.w:0);}if(std::abs(loss-drop)>std::max(1e-8,drop*1e-6))throw std::runtime_error("pressure residual");std::cout<<"pressure "<<drop<<" phase "<<r.phase<<" Q "<<first<<" residual "<<loss-drop<<"\n";}}
 if(powder::plant_discharge_ready(29400,30000,1.9)||powder::plant_discharge_ready(29399,30000,2.)||!powder::plant_discharge_ready(29400,30000,2.)||!powder::plant_discharge_ready(30000,30000,0.))throw std::runtime_error("test valve schedule regression");
 auto broken=d;broken[0].x=float(d.size()+1);bool rejected=false;try{powder::validate_plant_data(broken);}catch(...){rejected=true;}if(!rejected)throw std::runtime_error("invalid BVH accepted");
 if(argc>2){bool boundaryOnly=argc>3&&std::string(argv[3])=="boundary";if(argc>4||boundaryOnly)d[4].x=1;if(argc>3&&std::string(argv[3])=="resume_discharge")d[4].x=2;powder::GranularConfig c;c.plant=true;c.kernel_optimize=true;c.plant_data=d;c.radius=.00125f;c.dt=.00001f;c.iterations=8;
  std::ifstream f(root+"/test_charge.csv");std::string line;std::getline(f,line);std::vector<powder::Grain> p;
  while(std::getline(f,line)){std::replace(line.begin(),line.end(),',',' ');std::istringstream row(line);unsigned id,type;std::string supplier;float x,y,z,r,rho;if(!(row>>id>>type>>supplier>>x>>y>>z>>r>>rho)||id!=p.size())throw std::runtime_error("invalid charge row");p.push_back({x,y,z,float(type)});}
  if(argc>3&&std::string(argv[3])=="sparse"){std::vector<powder::Grain> small;for(size_t i=0;i<p.size();i+=1000)small.push_back(p[i]);p=small;}
  if(boundaryOnly)p.resize(1);c.count=unsigned(p.size());std::vector<powder::Grain> v(c.count);auto t=std::chrono::steady_clock::now();powder::GranularGPU gpu(c,p,v);if(argc>4){std::ifstream checkpoint(argv[4],std::ios::binary);std::uint32_t n=0;checkpoint.read(reinterpret_cast<char*>(&n),4);if(n!=p.size())throw std::runtime_error("checkpoint count mismatch");std::vector<powder::Grain> state(n),velocity(n);checkpoint.read(reinterpret_cast<char*>(state.data()),n*sizeof(powder::Grain));checkpoint.read(reinterpret_cast<char*>(velocity.data()),n*sizeof(powder::Grain));if(!checkpoint)throw std::runtime_error("truncated checkpoint");gpu.set_state(state,velocity);}
  std::cout<<"GPU "<<gpu.device()<<" count "<<p.size()<<std::endl;
  auto wall=gpu.inspect_boundaries({{-.8505f,1.4f,3.f,0},{0,0,.6035f,0}},0,false,false);if(wall[0].position.x>=-.8506f||(argc<=4&&!boundaryOnly&&wall[1].position.z<.6041f))throw std::runtime_error("source wall/closed gate projection failed");
  if(boundaryOnly){
   std::vector<powder::Grain> probes{{3,0,2.1635f,0},{3,0,2.1565f,0},{3.1395f,0,2.16f,0},{3.1394f,0,2.1634f,0}};
   auto hits=gpu.inspect_boundaries(probes,0,false,false);
   for(size_t k=0;k<probes.size();++k){auto a=probes[k],b=hits[k].position;double shift=std::hypot(std::hypot(a.x-b.x,a.y-b.y),a.z-b.z);if(!std::isfinite(shift)||shift>.002)throw std::runtime_error("finite valve rim produced excessive correction");}
   if(hits[0].position.z<2.16424f||hits[1].position.z>2.15576f||hits[2].position.x<3.14024f)throw std::runtime_error("finite valve face/rim contact failed");
   std::cout<<"PASS finite valve face and rounded-rim regression"<<std::endl;return 0;
  }
  double stageStart=0;unsigned steps=unsigned(std::stoul(argv[2]));for(unsigned i=0;i<steps;i+=16){gpu.advance(std::min(16u,steps-i),15,false);if(i%10000==0){auto a=gpu.snapshot();int wh=0,rh=0,mx=0;for(auto g:a){if(std::hypot(g.x,g.y)<.355&&g.z>.603&&g.z<1.78)++wh;if(std::hypot(g.x-3,g.y)<.255&&g.z>2.163&&g.z<3.7)++rh;if(g.x>2.25&&g.x<3.75&&std::abs(g.y)<.45&&g.z>.57&&g.z<1.31)++mx;}{std::ofstream checkpoint(root+"/probe_checkpoint.bin",std::ios::binary);auto velocity=gpu.velocity_snapshot();std::uint32_t n=unsigned(a.size());checkpoint.write(reinterpret_cast<char*>(&n),4);checkpoint.write(reinterpret_cast<const char*>(a.data()),a.size()*sizeof(powder::Grain));checkpoint.write(reinterpret_cast<const char*>(velocity.data()),velocity.size()*sizeof(powder::Grain));}std::cout<<"stage "<<d[4].x<<" t "<<gpu.time()<<" WH "<<wh<<" RH "<<rh<<" MX "<<mx<<std::endl;if((d[4].x==0&&wh==int(a.size()))||(d[4].x==1&&powder::plant_discharge_ready(rh,int(a.size()),gpu.time()-stageStart))){{std::ifstream src(root+"/probe_checkpoint.bin",std::ios::binary);std::ofstream dst(root+"/stage_"+std::to_string(int(d[4].x)+1)+"_checkpoint.bin",std::ios::binary);dst<<src.rdbuf();}d[4].x+=1;stageStart=gpu.time();gpu.update_plant_field(d);}}}auto after=gpu.snapshot();std::ofstream snapshot(root+"/last_probe.csv");snapshot<<"id,type,x,y,z\n";for(size_t i=0;i<after.size();++i)snapshot<<i<<','<<after[i].w<<','<<after[i].x<<','<<after[i].y<<','<<after[i].z<<'\n';double fall=0;for(size_t i=0;i<p.size();++i){if(after[i].w!=p[i].w)throw std::runtime_error("species changed");fall+=p[i].z-after[i].z;}std::cout<<std::setprecision(9)<<"PASS time "<<gpu.time()<<" wall "<<std::chrono::duration<double>(std::chrono::steady_clock::now()-t).count()<<" mean fall "<<fall/p.size()<<std::endl;
 }
 return 0;
}catch(const std::exception&e){std::cerr<<e.what()<<std::endl;return 1;}}
